"""Actual Monaco and Windows ConPTY in shared main/editor/Forge browser views."""
import argparse,json,sys,tempfile,threading
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from playwright.sync_api import sync_playwright,expect

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--output',type=Path,required=True);out=parser.parse_args().output;out.mkdir(parents=True,exist_ok=True)
    checks=[];errors=[]
    def passed(text):checks.append(text);print('PASS',text,flush=True)
    with tempfile.TemporaryDirectory(prefix='zenit-search-windows-') as tmp:
        base=Path(tmp);ws=base/'project';ws.mkdir();(ws/'src').mkdir()
        (ws/'src/main.py').write_text('😀 needle\n  needle\nAlpha alphabet ALPHA\n',encoding='utf-8');(ws/'note.txt').write_text('needle\n');external=base/'external.py';external.write_text('print("EXTERNAL_RUN_R4")\n')
        (ws/'ConsoleProbe.java').write_text('public class ConsoleProbe { public static void main(String[] args) { var c=System.console(); if(c==null) throw new IllegalStateException("No console"); System.out.println("FORGE_JAVA_TTY_OK"); System.out.println("FORGE_INPUT_"+c.readLine()); }}',encoding='utf-8')
        app=Application(ROOT,ws,data_dir=base/'profile');app.features.studio.update({'onboarded':True,'displayName':'Perfil de prueba'})
        app.features.prefs.update({'security.confirmRoutineActions':False,'general.showWelcome':False,'updates.automatic':False,'terminal.defaultProfile':'cmd'})
        app.workspace.trusted=True;server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start();url=f'http://127.0.0.1:{server.server_port}'
        try:
            with sync_playwright() as pw:
                browser=pw.chromium.launch(channel='msedge',headless=True);context=browser.new_context(viewport={'width':1672,'height':917})
                def inject(route):
                    r=route.fetch();route.fulfill(response=r,body=r.text()+'\nwindow.__qa={get studio(){return studio},get editor(){return editor},get platform(){return platformUI},openFile,showMenu,perform};')
                context.route('**/src/app.js',inject)
                def new_page(suffix=''):
                    p=context.new_page();p.on('pageerror',lambda e:errors.append(str(e)));p.on('dialog',lambda d:d.accept());p.goto(url+suffix);p.wait_for_function('window.lumen?.ready&&__qa.editor.kind==="monaco"');return p
                page=new_page();page.evaluate('__qa.openFile("src/main.py")');page.wait_for_function('__qa.editor.current==="src/main.py"')
                # The original point anchor has no contains(), focus(), or setAttribute().
                page.locator('#sidebar-content').click(button='right');expect(page.locator('#popover')).to_be_visible();page.locator('.monaco-editor').first.click(position={'x':130,'y':90});expect(page.locator('#popover')).to_be_hidden()
                page.locator('#sidebar-content').click(button='right');page.keyboard.press('Escape');expect(page.locator('#popover')).to_be_hidden()
                page.evaluate('__qa.perform("project-menu",document.querySelector("[data-action=project-menu]"))');expect(page.locator('#popover')).to_be_visible();page.locator('.topbar').click(position={'x':300,'y':20});expect(page.locator('#popover')).to_be_hidden();passed('Point and button menus close outside Monaco, on Escape, and without missing-method errors')
                page.keyboard.press('Control+Shift+f');expect(page.locator('#studio-search')).to_be_focused();page.locator('#studio-search').fill('needle');expect(page.locator('[data-search-result]')).to_have_count(3)
                expect(page.locator('.search-code mark')).to_have_count(3);page.get_by_role('button',name='src/main.py, línea 2',exact=True).click();page.wait_for_function('__qa.editor.current==="src/main.py"&&__qa.editor.view.getPosition().lineNumber===2&&__qa.editor.view.getPosition().column===3');passed('Every actual match opens its own line and UTF-16 column')
                page.keyboard.press('Control+Shift+f');expect(page.locator('#studio-search')).to_have_value('needle');page.locator('[data-search-filters]').click();page.locator('#search-extension').fill('*.py');expect(page.locator('[data-search-result]')).to_have_count(2)
                page.locator('#search-exclude').fill('src/**');expect(page.locator('[data-search-result]')).to_have_count(0);page.locator('#search-exclude').fill('');expect(page.locator('[data-search-result]')).to_have_count(2)
                page.locator('#studio-search').fill('alpha');expect(page.locator('.search-code mark')).to_have_count(3);page.locator('[data-search-option=word]').click();expect(page.locator('.search-code mark')).to_have_count(2);page.locator('[data-search-option=case]').click();expect(page.locator('[data-search-result]')).to_have_count(0);passed('Persistent search filters, exact words, case, and escaped inline highlights')
                page.locator('[data-search-option=case]').click();page.locator('[data-search-option=word]').click();page.locator('#studio-search').fill('needle');expect(page.locator('[data-search-result]')).to_have_count(2);page.locator('[data-search-filters]').click()
                for theme in ('day','dark'):
                    page.evaluate('(t)=>document.documentElement.dataset.theme=t',theme);page.screenshot(path=str(out/f'search-{theme}.png'),animations='disabled')
                for w,h in ((1366,768),(800,600),(640,480)):
                    page.set_viewport_size({'width':w,'height':h});assert not page.evaluate('document.documentElement.scrollWidth>innerWidth');expect(page.locator('#studio-search')).to_be_visible();page.screenshot(path=str(out/f'search-{w}x{h}.png'),animations='disabled')
                page.set_viewport_size({'width':1672,'height':917});page.locator('#studio-search').focus();page.keyboard.press('ArrowDown');page.keyboard.press('ArrowDown');page.keyboard.press('Enter');page.wait_for_function('__qa.editor.view.getPosition().lineNumber===2');passed('Search light/dark and three compact sizes; keyboard opens the second match')
                page.evaluate('async()=>{await __qa.platform.openTerminal("cmd");await __qa.studio.desktop.share("src/main.py")}');page.wait_for_function('!!__qa.platform.activeTerminal')
                session=page.evaluate('__qa.platform.activeTerminal');terminal=app.features.terminals.get(session);assert terminal.kind=='ConPTY/pywinpty'
                editor=new_page('/?panel=editor&file=src%2Fmain.py');editor.set_viewport_size({'width':1060,'height':760});expect(editor.locator('.native-editor-terminal')).to_be_visible();editor.locator('.native-editor-terminal').click();editor.wait_for_function('!!__qa.platform.activeTerminal');assert editor.evaluate('__qa.platform.activeTerminal')==session
                def send(p,name):
                    p.bring_to_front();p.locator('.pty-session:not([hidden]) .xterm-screen').click(position={'x':30,'y':30});p.locator('.pty-session:not([hidden]) .xterm-helper-textarea').focus();p.keyboard.type('echo '+name);p.keyboard.press('Enter');p.wait_for_function('(name)=>[...__qa.platform.terminals.values()].some(t=>t.xterm?.buffer.active.getLine(t.xterm.buffer.active.baseY)?.translateToString()!==undefined)&&document.hasFocus()',arg=name)
                    import time
                    end=time.monotonic()+10
                    while time.monotonic()<end:
                        if name+'\r\n' in terminal.read()['data'] and terminal.resize_owner==p.evaluate('__qa.platform.terminalView'):break
                        time.sleep(.05)
                    else:
                        p.screenshot(path=str(out/'terminal-failure.png'));print(repr(terminal.read()['data'][-2200:]),p.evaluate('({focus:document.hasFocus(),element:document.activeElement.className,view:__qa.platform.terminalView,active:__qa.platform.activeTerminal})'),terminal.resize_owner,flush=True);raise AssertionError('No shell output: '+name)
                send(editor,'EDITOR_TERMINAL_R4');assert terminal.resize_owner==editor.evaluate('__qa.platform.terminalView')
                draft='# child draft\nfrom pathlib import Path\n\ndef summarize(root: Path) -> int:\n    files = [p for p in root.rglob("*") if p.is_file()]\n    return len(files)\n\nprint(summarize(Path.cwd()))\n';editor.evaluate('(text)=>__qa.editor.models.get("src/main.py").model.setValue(text)',draft);page.wait_for_function('(text)=>__qa.editor.models.get("src/main.py").model.getValue()===text',arg=draft);send(page,'MAIN_TERMINAL_R4');assert terminal.resize_owner==page.evaluate('__qa.platform.terminalView');passed('Actual ConPTY accepts keyboard input in editor and main while the external editor shares dirty code')
                editor.bring_to_front();editor.keyboard.press('Control+j');expect(editor.locator('#terminal-panel')).to_be_hidden();editor.keyboard.press('Control+j');expect(editor.locator('#terminal-panel')).to_be_visible()
                geometry=editor.evaluate('()=>{const a=document.querySelector("#editor-panel").getBoundingClientRect(),b=document.querySelector("#terminal-panel").getBoundingClientRect();return {editorBottom:a.bottom,terminalTop:b.top,editorLeft:a.left,terminalLeft:b.left}}');assert geometry['terminalTop']>=geometry['editorBottom'] and abs(geometry['editorLeft']-geometry['terminalLeft'])<1,geometry
                handle=editor.get_by_role('separator',name='Altura del terminal');handle.focus();editor.keyboard.press('ArrowUp');expect(handle).to_have_attribute('aria-valuenow','33');editor.screenshot(path=str(out/'detached-editor-terminal.png'),animations='disabled')
                with editor.expect_popup() as popup:editor.evaluate('__qa.studio.desktop.detach("console")')
                console=popup.value;console.on('pageerror',lambda e:errors.append(str(e)));console.wait_for_function('window.lumen?.ready&&!!__qa.platform.activeTerminal');expect(editor.locator('#terminal-panel')).to_be_hidden();send(console,'NESTED_CONSOLE_R4');console.get_by_role('button',name='Volver al editor',exact=True).click();expect(editor.locator('#terminal-panel')).to_be_visible(timeout=10000);send(editor,'REINTEGRATED_R4');passed('Exterior terminal sits directly below code, resizes by keyboard, detaches, and returns without losing the shell')
                page.evaluate('__qa.editor.models.get("src/main.py").model.setValue("print(\\"RUN_SHARED_R4\\")\\n")');editor.wait_for_function('__qa.editor.getValue()==="print(\\"RUN_SHARED_R4\\")\\n"');editor.keyboard.press('Control+s');page.wait_for_function('!__qa.editor.isDirty("src/main.py")');assert (ws/'src/main.py').read_text()=='print("RUN_SHARED_R4")\n'
                page.evaluate('__qa.platform.savePreference("appearance.theme","dark")');editor.wait_for_function('document.documentElement.dataset.theme==="dark"');editor.evaluate('__qa.platform.savePreference("editor.fontSize",15)');page.wait_for_function('__qa.editor.view.getOption(monaco.editor.EditorOption.fontSize)===15');page.evaluate('__qa.studio.save({displayName:"Nombre compartido"})');editor.wait_for_function('__qa.studio.profile.displayName==="Nombre compartido"');passed('Edits, save state, theme, actual editor font, and profile identity synchronize in both directions')
                editor.evaluate('__qa.studio.host.api("/save",{path:"mirror.py",content:"# shared file\\n",create:true})');page.wait_for_function('__qa.studio.host.files().includes("mirror.py")');editor.wait_for_function('__qa.studio.host.files().includes("mirror.py")');editor.evaluate('__qa.platform.api("/files/operation",{operation:"delete",path:"mirror.py"})');page.wait_for_function('!__qa.studio.host.files().includes("mirror.py")');editor.wait_for_function('!__qa.studio.host.files().includes("mirror.py")');passed('Creating and deleting a file in the exterior window refreshes both project trees')
                editor.get_by_role('button',name='Usar terminal de Zénit',exact=True).click();expect(editor.locator('#terminal-panel')).to_be_hidden();send(page,'USE_MAIN_R4');editor.locator('[data-session-run]').click();expect(page.locator('#terminal-log')).to_contain_text('RUN_SHARED_R4',timeout=20000);expect(editor.locator('#terminal-log')).to_contain_text('RUN_SHARED_R4',timeout=20000);expect(editor.locator('#terminal-panel')).to_be_hidden();editor.locator('.native-editor-terminal').click();expect(editor.locator('#terminal-panel')).to_be_visible()
                for w,h in ((1060,760),(640,480),(380,320)):
                    editor.set_viewport_size({'width':w,'height':h});assert not editor.evaluate('document.documentElement.scrollWidth>innerWidth');geometry=editor.locator('.native-editor-shell').bounding_box();assert geometry['x']==0 and geometry['y']==0 and abs(geometry['width']-w)<1 and abs(geometry['height']-h)<1,geometry;assert editor.locator('.native-editor-run').evaluate('(e)=>getComputedStyle(e).color===getComputedStyle(e.querySelector(".icon")).color');editor.screenshot(path=str(out/f'exterior-full-{w}x{h}.png'),animations='disabled')
                editor.set_viewport_size({'width':1060,'height':760});passed('Full-window exterior editor has Run, mirrored actual Python output, and an option to keep using the main terminal')
                page.evaluate('(id)=>__qa.platform.selectTerminal(id)',session);forge=new_page('/?panel=forge');forge.set_viewport_size({'width':1060,'height':760});forge.wait_for_function('!!__qa.platform.activeTerminal');assert forge.evaluate('__qa.platform.activeTerminal')==session;send(forge,'FORGE_TERMINAL_R4');forge.screenshot(path=str(out/'forge-terminal.png'),animations='disabled');forge.close();editor.close();send(page,'AFTER_CHILD_CLOSE_R4');passed('Forge shares the live shell, Ctrl J toggles the exterior terminal, and child closing keeps the shell alive')
                page.evaluate('(path)=>__qa.openFile(path)',str(external));page.evaluate('async()=>await __qa.studio.desktop.share(__qa.editor.current)')
                external_editor=new_page('/?panel=editor&file='+__import__('urllib.parse',fromlist=['quote']).quote(str(external),safe=''));external_editor.locator('.native-editor-terminal').click();external_editor.wait_for_function('!!__qa.platform.activeTerminal');send(external_editor,'ABSOLUTE_FILE_R4');external_editor.close();passed('Absolute external file opened in the current session also has the actual terminal')
                external_editor=new_page('/?panel=editor&file='+__import__('urllib.parse',fromlist=['quote']).quote(str(external),safe=''));external_editor.locator('[data-session-run]').click();expect(external_editor.locator('#terminal-log')).to_contain_text('EXTERNAL_RUN_R4',timeout=20000);expect(page.locator('#terminal-log')).to_contain_text('EXTERNAL_RUN_R4',timeout=20000);external_editor.close();passed('Run executes an authorized absolute external file and shares actual output with the main application')
                java=new_page('/?panel=forge&file=ConsoleProbe.java');java.set_viewport_size({'width':1060,'height':760});java.locator('.forge-file-run').click();java.wait_for_function('()=>[...__qa.platform.terminals.values()].some(t=>t.profile.label.includes("ConsoleProbe.java"))',timeout=30000);sid=java.evaluate('__qa.platform.activeTerminal');program=app.features.terminals.get(sid);java.wait_for_function('()=>[...__qa.platform.terminals.values()].some(t=>{let lines=[];for(let i=0;i<t.xterm?.buffer.active.length;i++)lines.push(t.xterm.buffer.active.getLine(i)?.translateToString());return lines.join("\\n").includes("FORGE_JAVA_TTY_OK")})');java.locator('.pty-session:not([hidden]) .xterm-helper-textarea').focus();java.keyboard.type('hello');java.keyboard.press('Enter');java.wait_for_function('()=>[...__qa.platform.terminals.values()].some(t=>{let lines=[];for(let i=0;i<t.xterm?.buffer.active.length;i++)lines.push(t.xterm.buffer.active.getLine(i)?.translateToString());return lines.join("\\n").includes("FORGE_INPUT_hello")})');assert 'FORGE_INPUT_hello' in program.read()['data'];java.screenshot(path=str(out/'forge-java-console.png'),animations='disabled');java.close();passed('Forge actually compiles Java, provides System.console(), accepts input, and returns program output through ConPTY')
                # Real diff renderer and disposal; proposal data is an explicit fixture.
                count=page.evaluate('monaco.editor.getModels().length');page.evaluate('()=>__qa.platform.melodyFiles.open({summary:"Comparación de prueba",workspace:"project",operations:[{kind:"update",path:"src/main.py",before:"print(1)\\n",content:"print(2)\\n"}]},document.createElement("div"))');page.get_by_role('button',name='Comparar cambios').click();expect(page.locator('.melody-diff .monaco-diff-editor')).to_be_visible();assert page.evaluate('monaco.editor.getModels().length')==count+2;page.screenshot(path=str(out/'melody-diff.png'),animations='disabled');page.keyboard.press('Escape');page.wait_for_function('(n)=>monaco.editor.getModels().length===n',arg=count);passed('Real Monaco comparison renders and disposes both models on closing (proposal fixture)')
                assert not errors,errors;passed('No uncaught browser errors');browser.close()
        finally:server.shutdown();server.server_close();app.features.shutdown();app.runner.shutdown()
    (out/'verification.json').write_text(json.dumps({'checks':checks,'errors':errors,'shell':'Actual Windows ConPTY/CMD; keyboard sent in three separate renderer pages','aiTransport':'No model request; comparison uses declared proposal fixture'},indent=2),encoding='utf-8')

if __name__=='__main__':main()
